import React, { useState, useMemo, useRef } from 'react';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { exportarAExcel } from '../utils/exportUtils';
import {
    calcularTotalServicios,
    calcularGastosPorPropiedad,
    dividirGastosComunes,
    formatearMoneda
} from '../utils/calculos';

function ExportarMensual({ gastos, propiedades }) {
    const [mesSeleccionado, setMesSeleccionado] = useState(new Date().getMonth());
    const [añoSeleccionado, setAñoSeleccionado] = useState(new Date().getFullYear());
    const componenteImpresion = useRef();

    const gastosFiltrados = useMemo(() => {
        return gastos.filter(gasto => {
            const fechaGasto = new Date(gasto.fecha);
            return fechaGasto.getMonth() === mesSeleccionado &&
                fechaGasto.getFullYear() === añoSeleccionado;
        });
    }, [gastos, mesSeleccionado, añoSeleccionado]);

    const detalleInquilinos = useMemo(() => {
        const detalle = {};

        propiedades.forEach(propiedad => {
            const gastosPropiedad = gastosFiltrados.filter(
                g => g.propiedadId === propiedad.id ||
                    (!g.propiedadId && g.esCompartido)
            );

            const totalPropiedad = calcularGastosPorPropiedad(gastosPropiedad, propiedad.id);
            const gastosCompartidos = gastosFiltrados.filter(g => !g.propiedadId && g.esCompartido);
            const totalCompartido = calcularTotalServicios(gastosCompartidos);
            const parteIndividual = totalCompartido / (propiedad.inquilinos || 1);

            detalle[propiedad.nombre] = {
                propiedad,
                servicios: [
                    ...gastosPropiedad.filter(g => g.propiedadId === propiedad.id).map(g => ({
                        concepto: g.concepto,
                        montoTotal: g.monto,
                        montoIndividual: g.monto
                    })),
                    ...gastosCompartidos.map(g => ({
                        concepto: g.concepto + ' (Compartido)',
                        montoTotal: g.monto,
                        montoIndividual: g.monto / (propiedad.inquilinos || 1)
                    }))
                ],
                totalAPagar: totalPropiedad + parteIndividual
            };
        });

        return detalle;
    }, [gastosFiltrados, propiedades]);

    const handleExportarExcel = () => {
        const datos = {
            gastos: gastosFiltrados,
            totalGeneral: calcularTotalServicios(gastosFiltrados),
            totalesPorPropiedad: Object.fromEntries(
                propiedades.map(p => [p.nombre, calcularGastosPorPropiedad(gastosFiltrados, p.id)])
            ),
            detalleInquilinos
        };

        const nombreMes = format(new Date(añoSeleccionado, mesSeleccionado), 'MMMM', { locale: es });
        exportarAExcel(datos, nombreMes, añoSeleccionado);
    };

    const handleImprimir = () => {
        window.print();
    };

    const meses = [
        'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
        'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
    ];

    return (
        <div className="exportar-mensual">
            <h2>📥 Exportar Gastos Mensuales</h2>

            <div className="selector-periodo">
                <div className="form-grupo">
                    <label>Mes</label>
                    <select
                        value={mesSeleccionado}
                        onChange={(e) => setMesSeleccionado(parseInt(e.target.value))}
                    >
                        {meses.map((mes, index) => (
                            <option key={index} value={index}>{mes}</option>
                        ))}
                    </select>
                </div>

                <div className="form-grupo">
                    <label>Año</label>
                    <select
                        value={añoSeleccionado}
                        onChange={(e) => setAñoSeleccionado(parseInt(e.target.value))}
                    >
                        {[2024, 2025, 2026].map(año => (
                            <option key={año} value={año}>{año}</option>
                        ))}
                    </select>
                </div>
            </div>

            <div className="acciones-exportar">
                <button onClick={handleExportarExcel} className="btn-exportar">
                    📊 Exportar a Excel
                </button>
                <button onClick={handleImprimir} className="btn-exportar">
                    🖨️ Imprimir / PDF
                </button>
            </div>

            <div ref={componenteImpresion} className="vista-previa">
                <h3>Resumen {meses[mesSeleccionado]} {añoSeleccionado}</h3>

                <div className="total-general">
                    Total General: {formatearMoneda(calcularTotalServicios(gastosFiltrados))}
                </div>

                <div className="detalle-propiedades">
                    {Object.entries(detalleInquilinos).map(([nombre, detalle]) => (
                        <div key={nombre} className="propiedad-detalle">
                            <h4>
                                {nombre}
                                <span className="inquilino-info">
                                    ({detalle.propiedad.inquilinos} inquilinos)
                                </span>
                            </h4>

                            <table className="tabla-gastos">
                                <thead>
                                    <tr>
                                        <th>Concepto</th>
                                        <th>Total</th>
                                        <th>Por Inquilino</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {detalle.servicios.map((servicio, idx) => (
                                        <tr key={idx}>
                                            <td>{servicio.concepto}</td>
                                            <td>{formatearMoneda(servicio.montoTotal)}</td>
                                            <td>{formatearMoneda(servicio.montoIndividual)}</td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot>
                                    <tr>
                                        <td><strong>TOTAL A PAGAR</strong></td>
                                        <td colSpan="2">
                                            <strong>{formatearMoneda(detalle.totalAPagar)}</strong>
                                        </td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    ))}
                </div>

                {gastosFiltrados.length === 0 && (
                    <p className="sin-datos">No hay gastos registrados en este período</p>
                )}
            </div>
        </div>
    );
}

export default ExportarMensual;
